from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parent/'new'
cards=json.loads((ROOT/'cards.json').read_text()) if (ROOT/'cards.json').exists() else []
refs=json.loads((ROOT.parent/'catalog/remaining-references.json').read_text())
def add(n,name,category,style,icon,original,modern,stars=5,**extra):
 key=f'{n:03d}' if isinstance(n,int) else n
 source=next((r for r in refs if r['key']==key),{})
 c=dict(number=n,id='babidi-'+key.lower()+'-'+re.sub('[^a-z0-9]+','-',name.lower()).strip('-'),name=name,set='Babidi Saga',set_slug='babidi-saga',category=category,style=style,rarity_stars=stars,power_icon=icon,original_text=original,corrected_effect=modern,modern_rules=modern,icon_prefix='',source=source,original_scan='source/scans/'+key+'.jpg',crd='No card-specific erratum found in supplied Expanded CRD.',crd_source='source/Expanded-CRD.txt',release_status='artwork_pending',artwork_path='production/assets/artwork-'+key+'.png',artwork_fit='xMidYMid meet')
 c.update(extra);cards[:]=[x for x in cards if x['number']!=n];cards.append(c)
